  <style>
    :root {
      --blue-700: #0066ff;
      --blue-800: #0052cc;
      --blue-100: #eaf2ff;
      --teal-500: #13b8a6;
      --teal-600: #0fa392;
      --ink-900: #0f172a;
      --ink-700: #334155;
      --ink-500: #64748b;
      --gray-100: #f8fafc;
      --gray-200: #e2e8f0;
      --white: #ffffff;
      --shadow: 0 12px 28px rgba(15, 23, 42, 0.08);
      --radius-lg: 18px;
      --radius-md: 14px;
