    header {
      position: sticky;
      top: 0;
      z-index: 40;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid rgba(226, 232, 240, 0.65);
    }

    .header-inner {
      min-height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .logo {
      font-weight: 800;
      font-size: 1.4rem;
      color: var(--blue-700);
      letter-spacing: -0.03em;
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 1.1rem;
    }

    .nav-link {
      color: var(--ink-700);
      font-weight: 500;
      padding: 0.4rem 0.5rem;
      border-radius: 8px;
    }

    .nav-link:hover { color: var(--blue-700); background: var(--blue-100); }

    .menu-toggle {
      display: none;
      border: 0;
      background: transparent;
      width: 44px;
