      z-index: 60;
      padding: 1rem;
      display: flex;
      flex-direction: column;
      gap: 0.7rem;
    }

    .mobile-drawer.open { transform: translateX(0); }
    .mobile-link {
      min-height: 44px;
      display: flex;
      align-items: center;
      border-radius: 10px;
      padding: 0.7rem 0.8rem;
      font-weight: 600;
      color: var(--ink-700);
