    .mobile-link:hover { background: var(--gray-100); color: var(--blue-700); }

    .drawer-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(15, 23, 42, 0.36);
      opacity: 0;
      pointer-events: none;
      transition: opacity .25s ease;
      z-index: 50;
    }
    .drawer-backdrop.show { opacity: 1; pointer-events: auto; }

    .hero {
      background: linear-gradient(180deg, #f7fbff 0%, #fff 75%);
      padding: 4.5rem 0 2.5rem;
    }

    h1 {
      font-size: clamp(2rem, 4.8vw, 3.3rem);
      line-height: 1.12;
      margin: 0;
      letter-spacing: -0.03em;
    }

    .hero-subtitle {
      font-size: clamp(1rem, 2.2vw, 1.14rem);
      color: var(--ink-700);
