      align-items: center;
      padding-inline: 0.8rem;
      background: #fff;
    }

    .search-field input,
    .search-field select {
      width: 100%;
      border: 0;
      font-size: 1rem;
      color: var(--ink-900);
      background: transparent;
      min-height: 44px;
    }

    .search-field input::placeholder { color: var(--ink-500); }

    .search-submit {
      min-width: 132px;
      border-radius: 12px;
      font-size: 1rem;
    }

    .autocomplete {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      width: min(460px, 100%);
