  <script>
    const suggestions = [
      'Primary Care', 'Dentist', 'Dermatologist', 'Psychiatrist', 'Eye Doctor', 'Orthopedic Surgeon',
      'Migraine', 'Back pain', 'Allergies', 'Anxiety', 'Dr. Sarah Chen', 'Dr. Michael Rivera'
    ];

    const queryInput = document.getElementById('query');
    const suggestionList = document.getElementById('suggestionList');

    function renderSuggestions(value) {
      const needle = value.trim().toLowerCase();
      const filtered = suggestions
        .filter(item => item.toLowerCase().includes(needle))
        .slice(0, 6);

      suggestionList.innerHTML = '';

      if (!needle || filtered.length === 0) {
        suggestionList.classList.remove('open');
        queryInput.setAttribute('aria-expanded', 'false');
        return;
      }

      filtered.forEach((item, index) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'suggestion';
        btn.setAttribute('role', 'option');
        btn.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
        btn.textContent = item;
        btn.addEventListener('click', () => {
          queryInput.value = item;
          suggestionList.classList.remove('open');
          queryInput.setAttribute('aria-expanded', 'false');
        });
        suggestionList.appendChild(btn);
      });

      suggestionList.classList.add('open');
      queryInput.setAttribute('aria-expanded', 'true');
    }

    queryInput.addEventListener('input', (e) => renderSuggestions(e.target.value));

    document.addEventListener('click', (e) => {
      if (!suggestionList.contains(e.target) && e.target !== queryInput) {
        suggestionList.classList.remove('open');
        queryInput.setAttribute('aria-expanded', 'false');
      }
    });

    const menuToggle = document.getElementById('menuToggle');
    const mobileDrawer = document.getElementById('mobileDrawer');
    const drawerBackdrop = document.getElementById('drawerBackdrop');

    function closeDrawer() {
