        btn.addEventListener('click', () => {
          queryInput.value = item;
          suggestionList.classList.remove('open');
          queryInput.setAttribute('aria-expanded', 'false');
        });
        suggestionList.appendChild(btn);
      });

      suggestionList.classList.add('open');
      queryInput.setAttribute('aria-expanded', 'true');
    }

    queryInput.addEventListener('input', (e) => renderSuggestions(e.target.value));

    document.addEventListener('click', (e) => {
      if (!suggestionList.contains(e.target) && e.target !== queryInput) {
        suggestionList.classList.remove('open');
        queryInput.setAttribute('aria-expanded', 'false');
      }
    });

    const menuToggle = document.getElementById('menuToggle');
    const mobileDrawer = document.getElementById('mobileDrawer');
    const drawerBackdrop = document.getElementById('drawerBackdrop');

    function closeDrawer() {
      mobileDrawer.classList.remove('open');
      drawerBackdrop.classList.remove('show');
      menuToggle.setAttribute('aria-expanded', 'false');
    }

    menuToggle.addEventListener('click', () => {
      const willOpen = !mobileDrawer.classList.contains('open');
      mobileDrawer.classList.toggle('open');
      drawerBackdrop.classList.toggle('show');
      menuToggle.setAttribute('aria-expanded', String(willOpen));
    });

    drawerBackdrop.addEventListener('click', closeDrawer);
    mobileDrawer.querySelectorAll('a').forEach(link => link.addEventListener('click', closeDrawer));

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeDrawer();
    });
  </script>
